import reflex as rx
import httpx
import asyncio
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

# In-memory counters
counters = {
    "page_view": 0,
    "button_click": 0,
    "api_call": 0,
}

# Custom FastAPI application
fastapi_app = FastAPI()

class IncrementRequest(BaseModel):
    name: str
    amount: int = 1

@fastapi_app.get("/api/metrics")
def get_metrics():
    total = sum(counters.values())
    return {
        "counters": dict(counters),
        "total": total,
    }

@fastapi_app.post("/api/metrics/increment")
def increment_metric(req: IncrementRequest):
    if req.name not in counters:
        raise HTTPException(status_code=404, detail="Counter not found")
    counters[req.name] += req.amount
    total = sum(counters.values())
    return {
        "name": req.name,
        "value": counters[req.name],
        "total": total,
    }


class State(rx.State):
    """The app state."""
    counters_data: dict[str, int] = {
        "page_view": 0,
        "button_click": 0,
        "api_call": 0,
    }
    polling_active: bool = False

    @rx.var
    def derived_total(self) -> int:
        return sum(self.counters_data.values())

    @rx.event(background=True)
    async def start_polling(self):
        async with self:
            if self.polling_active:
                return
            self.polling_active = True

        while True:
            async with self:
                if not self.polling_active:
                    break

            try:
                async with httpx.AsyncClient() as client:
                    # Poll local backend
                    response = await client.get("http://127.0.0.1:8000/api/metrics", timeout=1.0)
                    if response.status_code == 200:
                        data = response.json()
                        async with self:
                            self.counters_data = data.get("counters", {})
            except Exception as e:
                # Ignore errors during startup/shutdown
                pass

            await asyncio.sleep(1.0) # Poll every 1.0 seconds


def index() -> rx.Component:
    return rx.center(
        rx.vstack(
            rx.heading("Live Metrics Dashboard", size="8", margin_bottom="4"),

            rx.vstack(
                rx.foreach(
                    State.counters_data,
                    lambda item: rx.hstack(
                        rx.text(item[0], font_weight="semibold", size="4"),
                        rx.badge(item[1].to(str), color_scheme="blue", size="3"),
                        justify="between",
                        width="100%",
                        padding_y="2",
                        border_bottom="1px solid #eaeaea",
                    )
                ),
                width="100%",
                background_color="#fcfcfc",
                padding="4",
                border_radius="md",
                box_shadow="sm",
                border="1px solid #eaeaea",
            ),

            rx.hstack(
                rx.text("Aggregate Total", font_weight="bold", size="5"),
                rx.badge(State.derived_total.to(str), color_scheme="green", size="3"),
                justify="between",
                width="100%",
                padding_top="4",
            ),

            spacing="4",
            width="400px",
            padding="6",
            border_radius="lg",
            box_shadow="lg",
            background_color="white",
            margin_y="8",
        ),
        min_height="100vh",
        background_color="#f5f5f5",
    )


app = rx.App(api_transformer=fastapi_app)
app.add_page(index, route="/", title="Live Metrics Dashboard", on_load=State.start_polling)

